import {editableHTML,editableText} from './rich-text.js?v=v1.7.3';
import {LANGUAGES,initialState,sampleRows,STORAGE_KEY} from './data.js?v=v1.7.3';
import {clone,normalizeText,languageCount,matchesCode,saveCodeMetadata,parseFile,inspectImport,applyImport,STATUS_LABELS} from './domain.js?v=v1.7.3';
import {ICONS,emptyContent,hasContent,completeContent,contentFor,translationOnly,syncTranslations,languageStatus,structureSignature,allocateBlock,validateEdit,migrateState} from './content.js?v=v1.7.3';
import {NOTES,ASSUMPTIONS} from './notes.js?v=v1.7.3';
import {parseMessageFile,inspectMessageImport,applyMessageImport,messageSample,messageCSV,exportMessageRows} from './message-import.js?v=v1.7.3';
const $=id=>document.getElementById(id);
const h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const now=()=>new Date().toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'});
const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
const language=id=>LANGUAGES.find(x=>x[0]===id)?.[1]||id;
const btn=(label,action,extra='',type='')=>`<button class="btn ${type}" data-action="${action}" ${extra}>${label}</button>`;
const link=(label,action,extra='',type='')=>`<button class="link ${type}" data-action="${action}" ${extra}>${label}</button>`;
const tag=(text,type='')=>`<span class="tag ${type}">${h(text)}</span>`;
const allowed=key=>!loadError&&ui.permissions.view&&ui.permissions[key];
const canEdit=()=>allowed('edit'),canManage=()=>allowed('manage'),canImport=()=>allowed('import'),canExport=()=>allowed('export');
let dbState,migrated=false,loadError='';
try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));if(saved?.schema){if(saved.schema<5||saved.demoCopyRevision!==2){const backup=saved.schema<5?STORAGE_KEY+'-before-v1.7-schema-'+saved.schema:STORAGE_KEY+'-before-v1.7.1-demo-copy';if(!localStorage.getItem(backup))localStorage.setItem(backup,JSON.stringify(saved));migrated=true;}dbState=migrateState(saved);localStorage.setItem(STORAGE_KEY,JSON.stringify(dbState));}else dbState=initialState();}catch{dbState=initialState();loadError='旧数据未改动，无法完成读取或备份，请保留原数据并重试。';}
const ui={view:'catalog',permissions:{view:true,manage:true,edit:true,import:true,export:true},scenario:'normal',fault:'none',filter:{query:''},page:1,overlay:null,draft:null,plan:null,importRows:null,importName:'',errors:{},busy:false,confirm:null,selectedNote:null,locale:'en',messageRows:null,messageName:'',messagePlan:null};
let toastTimer,renderedNoteContext=null,renderedOverlay=null,copyPinned=false;
function persist(next){localStorage.setItem(STORAGE_KEY,JSON.stringify(next));dbState=next;}
function toast(text,type='success'){$('toastRoot').innerHTML=`<div class="toast ${type}" role="status">${h(text)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toastRoot').innerHTML='',3800);}

function context(){return ui.overlay||ui.view;}

function renderNotes(){
 if(renderedNoteContext!==context()){ui.selectedNote=null;renderedNoteContext=context();}
 const notes=(NOTES[context()]||[]).filter(n=>$(n.target));
 const titles={catalog:'错误码目录',general:'编辑错误码文案',import:'导入错误码',metadata:'错误码基础信息',confirm:'变更影响确认','message-import':'批量导入多语言文案'};
 $('noteContext').textContent=titles[context()]||'错误码资源';
 $('noteList').innerHTML=notes.map(n=>`<section class="note-card ${ui.selectedNote===n.number?'active':''}" data-note="${n.number}" role="button" tabindex="0" aria-label="批注 ${n.number} ${h(n.title)}"><div class="note-heading"><span class="note-number">${n.number}</span><strong>${h(n.title)}</strong></div><p class="note-location">关联位置：${h(n.location)}</p><div class="note-body">${n.lines.map(([key,value])=>`<p class="${key==='原型备注'?'assumption':''}"><b>${h(key)}：</b>${h(value)}</p>`).join('')}</div></section>`).join('')+reviewExamples()+`<details class="note-card boundary-notes"><summary><strong>假设与交付边界</strong></summary><div class="note-body">${ASSUMPTIONS.map(([key,value])=>`<p><b>${h(key)}：</b>${h(value)}</p>`).join('')}</div></details>`;
 document.querySelectorAll('.note-anchor').forEach(e=>e.remove());
 for(const note of notes){const target=$(note.target);target.classList.add('anchor-host');target.classList.toggle('note-target-active',ui.selectedNote===note.number);const anchor=document.createElement('button');anchor.className='note-anchor';anchor.dataset.note=note.number;anchor.textContent=note.number;anchor.setAttribute('aria-label',`查看批注 ${note.number}：${note.title}`);target.append(anchor);}
 positionAnchors();
}

function reviewExamples(){
 if(!['import','message-import'].includes(context()))return '';
 const isCodeImport=context()==='import';
 return '<section class="note-card review-examples" aria-label="示例与演示"><strong>示例与演示</strong><p class="note-location">仅用于原型评审，载入示例会在本地预检查。</p><div class="review-example-actions">'+(isCodeImport?
 link('下载正常 CSV','download-sample')+link('下载冲突 JSON','download-conflict')+btn('载入正常示例','load-normal',canManage()?'':'disabled','small')+btn('载入冲突示例','load-conflict',canManage()?'':'disabled','small'):
 link('下载 JSON 示例','message-json')+btn('载入正常示例','message-sample',canImport()?'':'disabled','small')+btn('载入冲突示例','message-conflict',canImport()?'':'disabled','small'))+'</div></section>';
}
function showProductPane(){if(window.innerWidth>900)return;$('reviewShell').classList.remove('notes-mode');document.querySelectorAll('[data-mobile]').forEach(b=>b.classList.toggle('active',b.dataset.mobile==='product'));}
function positionAnchors(){
 const frame=document.querySelector('.product-frame').getBoundingClientRect();
 document.querySelectorAll('.note-anchor').forEach(anchor=>{const host=anchor.parentElement;if(getComputedStyle(host).position==='static')host.style.position='relative';const r=host.getBoundingClientRect();const left=Math.max(7,Math.min(r.width-30,frame.right-r.left-33));anchor.style.right='auto';anchor.style.left=left+'px';});
}

function selectNote(number){
 ui.selectedNote=number;
 document.querySelectorAll('.note-target-active').forEach(e=>e.classList.remove('note-target-active'));
 document.querySelectorAll('.note-card[data-note]').forEach(e=>e.classList.toggle('active',Number(e.dataset.note)===number));
 const note=(NOTES[context()]||[]).find(n=>n.number===number);const target=note&&$(note.target);
 if(target){target.classList.add('note-target-active');if(!ui.overlay)target.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'});}
 const card=document.querySelector(`.note-card[data-note="${number}"]`);card?.scrollIntoView({block:'nearest'});
}

function pageState(){
 if(ui.scenario==='loading')return `<div id="pageState" class="empty-state"><span class="spinner"></span><h3>正在加载错误码配置</h3><p>请稍候</p></div>`;
 if(ui.scenario==='error')return `<div id="pageState" class="empty-state"><span class="empty-icon">!</span><h3>配置加载失败</h3><p>请检查连接后重试，当前有效配置仍然保留。</p>${btn('重新加载','retry','', 'primary')}</div>`;
 return '';
}

function tableBottom(total){return `<div id="tableBottom" class="table-bottom"><p>语言完成度按完整语言数 / 16 计算；缺译文不在目录回填。</p><div class="pagination"><span>共 ${total} 条</span>${btn('‹','previous',ui.page<=1?'disabled':'','small')}<span class="page-num">${ui.page}</span>${btn('›','next',ui.page*10>=total?'disabled':'','small')}<select aria-label="每页条数" disabled><option>10 条/页</option></select></div></div>`;}

function renderMain(){$('roleName').textContent='当前平台账号';if(loadError){$('adminMain').innerHTML='<div class="empty-state"><h3>数据读取未完成</h3><p>'+h(loadError)+'</p></div>';return;}if(!ui.permissions.view){$('adminMain').innerHTML='<div class="empty-state"><h3>暂无查看权限</h3><p>请联系平台权限维护者。</p></div>';return;}$('adminMain').innerHTML=mainHeader()+catalogPage()+'</div></div>';}

function drawer(title,body,footer,width=''){return `<div class="scrim" data-scrim><section class="drawer" role="dialog" aria-modal="true" aria-label="${h(title)}" ${width?`style="width:${width}"`:''}><header class="drawer-header"><h3>${title}</h3><button class="icon-btn" data-action="close" aria-label="关闭抽屉" ${ui.busy?'disabled':''}>×</button></header><div class="drawer-body">${body}${ui.errors.submit?`<div class="error-list mt" role="alert">${h(ui.errors.submit)}</div>`:''}</div><footer id="editFooter" class="drawer-footer">${footer}</footer></section></div>`;}

function codeSummary(id){const c=dbState.codes[id];return `<div id="editSummary" class="readonly-summary"><div class="wide"><span class="label">标准码</span><code>${h(id)}</code></div><div><span class="label">含义说明</span>${h(c.description)||'未填写'}</div></div>`;}

function metadataDrawer(){const d=ui.metadata;return drawer(d.editing?'编辑标准语义':'新增错误码',`<section id="metadataFields"><div class="form-row"><label class="required" for="metadataCode">错误码</label><input id="metadataCode" value="${h(d.code)}" ${d.editing?'readonly':''} placeholder="例如 AA-002-0x01"><span class="muted">创建后不可修改；保留原始大小写。</span></div><div class="form-row"><label for="metadataDescription">标准语义 <span class="muted">（选填）</span></label><textarea id="metadataDescription" rows="3" placeholder="选填，填写已确认的错误码含义">${h(d.description)}</textarea></div><p class="muted">${d.editing?'仅更新标准语义，文案及正文结构保持原样。':'先建立条目，再进入编辑文案配置共用结构和各语言内容。'}</p>${ui.errors.metadata?`<div class="error-list" role="alert">${h(ui.errors.metadata)}</div>`:''}</section>`,`<span class="muted">基础信息单独保存</span>${btn('取消','close')}${btn('保存','save-metadata','','primary')}`,'min(600px, calc(100% - 12px))');}
function openMetadata(code){if(!canManage())return;ui.metadata={editing:!!code,code:code||'',description:code?dbState.codes[code].description:'',baseVersion:dbState.version};ui.overlay='metadata';ui.errors={};renderEditor();}
function saveMetadata(){if(!canManage())return;const d=clone(ui.metadata);try{saveCodeMetadata(dbState,d.code,d.description,d.editing);ui.errors={};askConfirm(d.editing?'确认更新标准语义':'确认新增错误码',`<p>错误码：<code>${h(d.code.trim())}</code></p><p>标准语义：${h(d.description.trim())||'未填写'}</p><p>${d.editing?'已有文案和正文结构保留。':'将建立空白文案条目，语言完成度为 0/16。'}</p>`,()=>{if(!canManage())throw new Error('没有错误码维护权限，本次未写入。');return commit(next=>saveCodeMetadata(next,d.code,d.description,d.editing,now()),'维护错误码基础信息 · '+d.code.trim(),d.baseVersion);},'metadata');}catch(e){ui.errors.metadata=e.message;renderEditor();$('metadataDescription').focus();}}
function importDrawer(){let report='';if(ui.plan){const p=ui.plan;report=`<section id="importReport"><div class="section-title">预检查结果 ${tag(p.valid?'校验通过':'整批不可导入',p.valid?'success':'danger')}</div><div class="import-counts">${[['added','新增'],['updated','更新'],['unchanged','无变化'],['conflict','冲突']].map(([id,label])=>`<div><strong class="${id==='conflict'&&p.counts[id]?'err':''}">${p.counts[id]}</strong>${label}</div>`).join('')}</div>${p.errors.length?`<div class="error-list">${p.errors.map(error=>`<p>${h(error)}</p>`).join('')}<p><strong>存在错误，本批次不会写入任何条目。</strong></p></div>`:''}<div class="import-table"><table class="data-table"><thead><tr><th>数据行</th><th>错误码</th><th>标准语义 / 变更</th><th>结果</th></tr></thead><tbody>${p.rows.map(r=>`<tr><td>${r.line}</td><td><code>${h(r.normalizedCode)}</code></td><td>${h(r.description)||'未填写'}${r.status==='updated'?`<span class="cell-sub">原：${h(r.before)||'未填写'}</span>`:''}${r.error?`<p class="field-error">${h(r.error)}</p>`:''}</td><td>${tag(STATUS_LABELS[r.status],r.status==='conflict'?'danger':r.status==='updated'?'warning':r.status==='added'?'success':'')}</td></tr>`).join('')}</tbody></table></div></section>`;}
 return drawer('导入错误码',`<section id="codeImportRules" class="notice"><strong>批量新增错误码或更新标准语义。</strong><p>模板包含“错误码”和“标准语义”两列；错误码必填，标准语义选填。</p><p>新错误码未填写标准语义也可建立空白文案条目，语言完成度为 0/16；已存在的错误码仅在填写非空标准语义时更新，留空或未提供时保留原值。全部文案、正文结构及文件未包含的条目保持不变。需要清空标准语义，请手动编辑。</p><p>需要填写或修改多语言标题、摘要和正文主副文案，请使用“批量导入文案”。</p></section>${!canManage()?'<div class="notice mt">当前仅可下载模板；上传、预检查和提交需要错误码维护权限。</div>':''}<section id="importFile" class="mt"><label class="dropzone" id="dropzone"><div class="upload-symbol">↑</div><strong>${ui.importName?h(ui.importName):'点击选择文件，或拖拽文件到此处'}</strong><span>CSV / JSON · 错误码、标准语义</span><input id="codeFile" ${canManage()?'':'disabled'} type="file" accept=".csv,.json" aria-label="选择码表文件"></label><div class="import-template-row">${link('下载导入模板','download-code-template')}<span class="muted">错误码必填，标准语义选填</span></div>${ui.errors.file?`<div class="error-list" role="alert">${h(ui.errors.file)}</div>`:''}</section>${report}`,`<span class="muted">确认前不修改目录</span>${btn('取消','close',ui.busy?'disabled':'')}${btn('预检查','inspect',!ui.importRows||ui.busy||!canManage()?'disabled':'')}${btn(ui.busy?'导入中':'确认导入','import-confirm',!ui.plan?.valid||ui.busy||!canManage()?'disabled':'','primary')}`);}

function confirmModal(){const c=ui.confirm;return `<div class="scrim modal-scrim"><section class="modal" role="dialog" aria-modal="true" aria-label="${h(c.title)}"><header class="drawer-header"><h3>${h(c.title)}</h3><button class="icon-btn" data-action="cancel-confirm" aria-label="关闭确认框" ${ui.busy?'disabled':''}>×</button></header><div id="confirmBody" class="modal-content">${c.body}${ui.errors.submit?`<div class="error-list">${h(ui.errors.submit)}</div>`:''}</div><footer id="confirmFooter" class="drawer-footer">${btn('取消','cancel-confirm',ui.busy?'disabled':'')}${btn(ui.busy?'<span class="spinner"></span> 处理中':c.label||'确认保存','confirm-submit',ui.busy?'disabled':'','primary')}</footer></section></div>`;}

function askConfirm(title,body,task,returnTo=ui.overlay,label='确认保存'){ui.confirm={title,body,task,returnTo,label};ui.overlay='confirm';ui.errors.submit='';ui.selectedNote=null;renderEditor();}

function cancelConfirm(){if(ui.busy)return;ui.overlay=ui.confirm.returnTo;ui.confirm=null;ui.errors.submit='';renderEditor();}

async function commit(mutator,message,baseVersion){
 if(!ui.permissions.view)throw new Error('没有查看权限，本次未写入。');
 const stored=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(stored&&stored.version!==dbState.version){dbState=migrateState(stored);throw new Error('配置已被其他窗口更新，请重新检查后提交。');}
 if(ui.fault==='save'){ui.fault='none';$('demoFault').value='none';throw new Error('保存失败，请重试。当前生效配置未改变。');}
 if(ui.fault==='concurrent'){ui.fault='none';$('demoFault').value='none';const concurrent=clone(dbState);concurrent.version++;concurrent.updated=now();concurrent.lastChange='其他管理员已更新配置（并发演示）';persist(concurrent);throw new Error('配置已被其他操作更新，请重新检查后提交。');}
 if(baseVersion!==undefined&&dbState.version!==baseVersion)throw new Error('配置已发生变化，请重新预检查或打开编辑。');
 const prev=clone(dbState);const next=mutator(clone(dbState));next.version=prev.version+1;next.updated=now();for(const id of Object.keys(next.codes))if(!prev.codes[id])next.codes[id].updated=next.updated;next.lastChange=message;persist(next);
}

async function submitConfirm(){if(ui.busy)return;ui.busy=true;ui.errors.submit='';renderEditor();await sleep(650);try{await ui.confirm.task();ui.busy=false;ui.confirm=null;ui.errors={};ui.overlay=null;ui.draft=null;ui.plan=null;render();toast('操作成功，配置已保存。');}catch(error){ui.busy=false;ui.errors.submit=error.message;renderMain();renderEditor();}}

function inspect(){ui.errors.file='';try{ui.plan=inspectImport(dbState,ui.importRows);}catch(error){ui.plan=null;ui.errors.file=error.message;}renderEditor();}

async function readCodes(file){if(!file||!canManage())return;ui.importName=file.name;ui.plan=null;ui.errors.file='';ui.importRows=null;try{ui.importRows=parseFile(await file.text(),file.name);}catch(error){ui.errors.file='文件解析失败：'+error.message;}renderEditor();}

function importConfirm(){if(!canManage()||!ui.plan?.valid)return;const p=clone(ui.plan);if(!p.counts.added&&!p.counts.updated){ui.overlay=null;ui.plan=null;render();toast('全部条目无变化，无需写入。','info');return;}askConfirm('确认导入错误码',`<p>将新增 ${p.counts.added} 个错误码，更新 ${p.counts.updated} 项标准语义；${p.counts.unchanged} 条无变化跳过。</p><div class="confirm-impact"><span>新码建立空白文案条目，完成度为 0/16。</span><span>已有文案、共用结构和文件未包含的条目保留。</span></div>`,()=>{if(!canManage())throw new Error('没有错误码维护权限，本次未写入。');return commit(next=>applyImport(next,p,now()),'导入错误码',p.baseVersion);},'import','确认导入');}
function download(kind='normal'){
 const header='\uFEFFnormalizedCode,description\n',rows=sampleRows(kind),csv=kind!=='conflict';
 const text=kind==='template'?header:csv?header+rows.map(r=>[r.normalizedCode,r.description].map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n'):JSON.stringify(rows,null,2);
 downloadText(text,kind==='template'?'error-code-template.csv':csv?'error-code-example.csv':'error-code-conflict.json',csv?'text/csv;charset=utf-8':'application/json');
}

function mainHeader(){return `<div id="pageHead" class="page-head"><h2>错误码资源</h2>${tag('配网失败','primary')}</div><p class="page-subtitle">维护错误码、标准语义及多语言指引文案。</p><div class="page-meta"><span>${Object.keys(dbState.codes).length} 个错误码</span><span>更新于 ${h(dbState.updated)}</span></div><div class="panel"><div class="panel-body">`;}
function catalogPage(){
 let entries=Object.entries(dbState.codes).filter(([id,c])=>matchesCode(id,c,ui.filter.query));
 if(ui.scenario==='empty')entries=[];const count=entries.length;entries=entries.slice((ui.page-1)*10,ui.page*10);
 return `<div id="filterBar" class="filter-bar"><div class="filter-field catalog-search"><label for="searchQuery">错误码 / 标准语义 / 多语言标题与摘要</label><input id="searchQuery" placeholder="输入错误码、标准语义或任意语言的标题 / 摘要" value="${h(ui.filter.query)}"></div>${btn('查询','search','','primary')}${btn('重置','reset-filter')}</div><div id="actionBar" class="action-bar">${btn('＋ 新增错误码','new-code',canManage()?'':'disabled','primary')}${btn('导入错误码','open-import')}${btn('批量导入文案','open-message-import')}${btn('导出当前文案','export-messages',canExport()?'':'disabled')}</div>
 ${pageState()||`<div id="catalogTable">${count?`<div class="catalog-scroll" tabindex="0" aria-label="16语言目录，可横向滚动"><table class="data-table catalog-table"><colgroup><col style="width:230px">${LANGUAGES.map(()=>'<col style="width:240px">').join('')}<col style="width:120px"><col style="width:164px"><col style="width:124px"></colgroup><thead><tr><th class="sticky-code">错误码 / 标准语义</th>${LANGUAGES.map(([id,label])=>`<th data-language-column="${id}">${h(label)}</th>`).join('')}<th>语言完成度</th><th>更新时间</th><th class="sticky-operations">操作</th></tr></thead><tbody>${entries.map(([id,c])=>`<tr><td class="sticky-code"><span class="code">${h(id)}</span><span class="cell-sub">${h(c.description)||'未填写'}</span></td>${LANGUAGES.map(([locale,label])=>{const copy=c.content[locale];return `<td>${copy&&(copy.title||copy.summary)?`<button class="locale-copy" data-action="full-copy" data-code="${h(id)}" data-locale="${locale}" aria-label="查看 ${h(id)} ${h(label)}标题和摘要全文"><span class="copy-title">${h(copy.title)||'未配置标题'}</span><span class="copy-summary">${h(copy.summary)||'未配置摘要'}</span></button>`:'<span class="unconfigured-copy">未配置</span>'}</td>`;}).join('')}<td><div class="coverage"><span>${languageCount(c,LANGUAGES)}/16</span><span class="coverage-track"><span style="width:${languageCount(c,LANGUAGES)/16*100}%"></span></span></div></td><td><span class="muted">${h(c.updated)}</span></td><td class="sticky-operations">${link('编辑文案','general',`data-code="${h(id)}" ${canEdit()?'':'disabled'}`)}${link('编辑语义','edit-metadata',`data-code="${h(id)}" ${canManage()?'':'disabled'}`)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><span class="empty-icon">▤</span><h3>${ui.filter.query?'没有符合条件的错误码':'暂无错误码资源'}</h3><p>${ui.filter.query?'请调整关键字或重置查询。':'可手动新增错误码，或导入错误码与标准语义码表。'}</p>${ui.filter.query?btn('重置查询','reset-filter'):btn('新增错误码','new-code',canManage()?'':'disabled','primary')}</div>`}</div>`}${tableBottom(count)}`;
}

function iconGlyph(id){const paths={wifi:'M3 8a14 14 0 0 1 18 0M6 12a9 9 0 0 1 12 0M9 16a4 4 0 0 1 6 0M12 20h.01',bluetooth:'M7 7l10 10-5 4V3l5 4L7 17',warning:'M12 3L2 21h20L12 3zM12 9v5M12 17h.01',settings:'M4 7h16M4 17h16M8 4v6M16 14v6',check:'M5 12l4 4L19 6',info:'M12 11v6M12 7h.01'};return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${id==='info'?'<circle cx="12" cy="12" r="9"/>':''}<path d="${paths[id]||paths.info}"/></svg>`;}
function richField(b,index,field,label){const id=`block-${index}-${field}`;return `<div class="rich-field ${field}"><div class="rich-heading"><label id="${id}-label" class="required">${label}</label><button class="format-button" data-action="bold" data-target="${id}" title="选中文字后加粗；再次点击取消" aria-label="${label}加粗"><b>B</b> 加粗</button></div><div id="${id}" class="rich-input" contenteditable="true" role="textbox" aria-labelledby="${id}-label" aria-multiline="true" data-block="${index}" data-field="${field}" data-placeholder="${field==='primary'?'填写主文案':'填写补充说明，可换行'}">${editableHTML(b[field])}</div></div>`;}
function generalDrawer(){
 const d=ui.draft,c=contentFor(d,ui.locale);
 return drawer('编辑错误码文案',`${codeSummary(d.code)}<div id="languageTabs" class="locale-selector" role="tablist" aria-label="文案语言">${LANGUAGES.map(([id,label])=>`<button role="tab" aria-selected="${id===ui.locale}" class="locale-tab ${id===ui.locale?'active':''} ${ui.errors[id]?'invalid':''}" data-action="locale" data-locale="${id}">${h(label)}<span class="locale-dot ${languageStatus(d,id)==='complete'?'done':languageStatus(d,id)==='pending'?'partial':''}" title="${languageStatus(d,id)==='complete'?'已完整配置':languageStatus(d,id)==='pending'?'待补齐':'未配置'}"></span></button>`).join('')}</div><p class="language-caption">${h(language(ui.locale))} · ${tag(({complete:'完整',pending:'待补齐',unconfigured:'未配置'})[languageStatus(d,ui.locale)],languageStatus(d,ui.locale)==='complete'?'success':languageStatus(d,ui.locale)==='pending'?'warning':'')} · ${ui.locale==='en'?'默认语言，完整配置后可保存':'选填语言；不完整时整份使用英语'}</p>${ui.errors[ui.locale]?`<div class="error-list" role="alert">${ui.errors[ui.locale].map(e=>`<p>${h(e)}</p>`).join('')}</div>`:''}<section id="messageFields" class="content-fields"><div class="section-title">当前语言文案</div><div class="form-row"><label class="required" for="contentTitle">标题</label><input id="contentTitle" data-content="title" placeholder="填写错误提示标题" value="${h(c.title)}"></div><div class="form-row"><label class="required" for="contentSummary">摘要</label><textarea id="contentSummary" data-content="summary" rows="2" placeholder="简要说明错误情况">${h(c.summary)}</textarea></div></section><section id="blockFields" class="block-section"><div class="section-title">共用正文结构 <span class="block-count">${c.blocks.length} 个 Block</span>${btn('＋ 添加 Block','add-block','','small')}</div><p class="block-help">Block 数量、顺序及前缀对所有语言生效；主副文案按当前语言填写并同时展示。选择文字后点击加粗；支持回车或字面量 <code>\\n</code> 换行。</p><div class="notice">调整共用结构后，英语完整即可保存；其他语言可先待补齐，再下载新模板批量补译。普通文案修改须将本次修改的语言补齐后保存。</div><div class="block-list">${c.blocks.map((b,i)=>`<article class="block-card"><header class="block-header"><strong>Block ${i+1}</strong><span class="block-id">${h(b.id)}</span><div class="block-actions">${btn('上移','move-block',`data-index="${i}" data-direction="-1" ${i===0?'disabled':''}`,'small')}${btn('下移','move-block',`data-index="${i}" data-direction="1" ${i===c.blocks.length-1?'disabled':''}`,'small')}${link('移除','remove-block',`data-index="${i}"`,'danger')}</div></header><div class="prefix-row">${b.prefixType==='none'?'':`<span class="prefix-symbol">${b.prefixType==='icon'?iconGlyph(b.icon):h(b.number)}</span>`}<div class="prefix-field"><label for="prefix-${i}">前缀类型</label><select id="prefix-${i}" data-block="${i}" data-field="prefixType"><option value="none" ${b.prefixType==='none'?'selected':''}>无</option><option value="number" ${b.prefixType==='number'?'selected':''}>数字前缀</option><option value="icon" ${b.prefixType==='icon'?'selected':''}>图标</option></select></div>${b.prefixType==='icon'?`<div class="prefix-field"><label for="icon-${i}">选择图标</label><select id="icon-${i}" data-block="${i}" data-field="icon">${ICONS.map(([id,label])=>`<option value="${id}" ${id===b.icon?'selected':''}>${h(label)}</option>`).join('')}</select></div>`:b.prefixType==='number'?`<div class="prefix-field"><label for="number-${i}">数字</label><input id="number-${i}" data-block="${i}" data-field="number" inputmode="numeric" value="${h(b.number)}"></div>`:''}</div><div class="block-copy">${richField(b,i,'primary','主文案')}${richField(b,i,'secondary','副文案')}</div></article>`).join('')||`<div class="block-empty">暂无正文 Block，点击“添加 Block”开始配置。</div>`}</div></section>`,`<span class="muted">保存当前错误码的所有语言；取消不写入</span>${btn('取消','close')}${btn('保存','save-general',ui.busy?'disabled':'','primary')}`);
}
function renderOverlay(){const changed=renderedOverlay!==ui.overlay;renderedOverlay=ui.overlay;const templates={general:generalDrawer,metadata:metadataDrawer,import:importDrawer,confirm:confirmModal,'message-import':messageImportDrawer};$('overlayRoot').innerHTML=ui.overlay?templates[ui.overlay]():'';$('productCanvas').inert=!!ui.overlay;if(ui.busy)$('overlayRoot').querySelectorAll('input,select,textarea,button').forEach(c=>c.disabled=true);if(changed&&ui.overlay)requestAnimationFrame(()=>$('overlayRoot').querySelector('button:not(:disabled)')?.focus({preventScroll:true}));}
function render(){hideFullCopy();renderMain();renderOverlay();renderNotes();}
function renderEditor(){hideFullCopy();const scroll=$('overlayRoot').querySelector('.drawer-body')?.scrollTop||0;renderOverlay();renderNotes();const body=$('overlayRoot').querySelector('.drawer-body');if(body)body.scrollTop=scroll;}
function close(){if(ui.busy)return;if(ui.overlay==='confirm'){cancelConfirm();return;}ui.overlay=null;ui.draft=null;ui.errors={};render();}
function openGeneral(code){if(!canEdit())return;ui.draft={...clone(dbState.codes[code]),code,baseVersion:dbState.version};ui.locale='en';ui.errors={};ui.overlay='general';renderEditor();}
function currentContent(){if(!ui.draft.content[ui.locale])ui.draft.content[ui.locale]=translationOnly(contentFor(ui.draft,ui.locale));return ui.draft.content[ui.locale];}
function saveGeneral(){
 if(!canEdit())return;const result=validateEdit(dbState.codes[ui.draft.code],ui.draft);ui.errors=result.errors;
 if(Object.keys(ui.errors).length){ui.locale=Object.keys(ui.errors)[0];renderEditor();const issue=ui.errors[ui.locale][0],block=issue.match(/Block (\d+)/);const target=issue.includes('标题')?'contentTitle':issue.includes('摘要')?'contentSummary':block?('block-'+(Number(block[1])-1)+'-'+(issue.includes('副文案')?'secondary':'primary')):null;if(target)$(target)?.focus();else document.querySelector('[data-action="add-block"]')?.focus();return;}
 const draft=clone(ui.draft),pending=LANGUAGES.filter(([id])=>languageStatus(draft,id)==='pending').map(([id])=>language(id));
 if(structureSignature(dbState.codes[draft.code])===structureSignature(draft)&&JSON.stringify(dbState.codes[draft.code].content)===JSON.stringify(Object.fromEntries(Object.entries(draft.content).filter(([,c])=>hasContent(c))))){close();toast('全部文案无变化，无需写入。','info');return;}
 askConfirm('确认保存错误码文案',`<p>将保存当前错误码的共用结构与多语言文案。</p><div class="confirm-impact"><span>标准码：<code>${h(draft.code)}</code></span><span>完整语言：${languageCount(draft,LANGUAGES)} / 16</span><span>Block 数量、顺序及前缀由所有语言共用。</span>${pending.length?`<span>待补齐：${h(pending.join('、'))}；补齐前整份回退英语。</span>`:''}</div>`,()=>{if(!canEdit())throw new Error('没有文案维护权限，本次未写入。');return commit(next=>{const code=next.codes[draft.code];code.structure=clone(draft.structure);code.usedBlockIds=clone(draft.usedBlockIds);code.content=Object.fromEntries(Object.entries(draft.content).filter(([,c])=>hasContent(c)).map(([id,c])=>[id,translationOnly(contentFor(draft,id))]));code.updated=now();return next;},'更新错误码文案 · '+draft.code,draft.baseVersion);});
}
function openMessageImport(){if(!ui.permissions.view)return;ui.overlay='message-import';ui.messageRows=null;ui.messagePlan=null;ui.messageName='';ui.errors={};renderEditor();}
const fieldLabel=id=>({title:'标题',summary:'摘要',blockOrder:'排序',prefixType:'前缀类型',icon:'图标',number:'数字前缀',primary:'主文案',secondary:'副文案'}[id]||id);
function messageImportDrawer(){const plan=ui.messagePlan;return drawer('批量导入多语言文案',`<section id="messageImportRules" class="notice"><strong>批量填写或更新已有错误码的多语言指引文案。</strong><p>导入内容包括各语言的标题、摘要，以及已配置正文 Block 的主文案和副文案，适用于集中翻译、补齐语言或批量修改文字。请先通过“新增错误码”或“导入错误码”建立条目，并手动配置正文结构。</p><p>语言作为列，同一内容项的多语言放在同一行。</p><p>按错误码、Block 标识与内容项定位；所有语言共用已保存的正文结构；仅更新文案，非空语言单元格更新，空白保留。未包含的语言与 Block 保留。本次修改的语言合并后须完整；待补齐语言未修改时不阻断。</p><p>新增、移除、排序 Block 或调整前缀，请进入“编辑文案”手动操作。</p></section><section id="messageImportFormat" class="import-format"><div class="section-title">文案模板说明</div><p>固定列：错误码、Block 标识、内容项。</p><p>语言列：英语、中文、德语等16种语言，同一内容项的各语言文案在同一行横向对照。</p><p>内容项为标题、摘要、主文案或副文案。标题和摘要各占一行，Block 标识留空；每个已配置 Block 的主文案和副文案各占一行，填写对应 Block 标识。</p><p>仅支持标题、摘要、主文案和副文案。Block 标识用于定位已手动配置的正文，不支持通过导入变更结构。</p><p><code>**文字**</code> 加粗 · <code>\\n</code> 换行。下载模板和导出文件使用相同列结构，可直接修改后再导入。</p><details><summary>查看语言编码</summary><p>${LANGUAGES.map(([id,label])=>`${h(label)}：<code>${id}</code>`).join(' · ')}</p></details></section><section id="messageImportFile"><label class="dropzone" id="messageDropzone"><div class="upload-symbol">↑</div><strong>${ui.messageName?h(ui.messageName):'选择或拖拽多语言文案文件'}</strong><span>CSV / JSON · 语言列模板 · 一项一行</span><input id="messageFile" ${canImport()?'':'disabled'} type="file" accept=".csv,.json" aria-label="选择多语言文案文件"></label><div class="import-template-row">${link('下载导入模板','message-template')}<span class="muted">按当前已配置的结构生成，填写或修改语言文案</span></div>${ui.errors.file?`<div class="error-list" role="alert">${h(ui.errors.file)}</div>`:''}</section>${plan?`<section id="messageImportReport"><div class="section-title">预检查结果 ${tag(plan.valid?'校验通过':'整批不可导入',plan.valid?'success':'danger')}</div><div class="import-counts">${[['added','新增单元格'],['updated','更新单元格'],['unchanged','无变化'],['conflict','错误项']].map(([key,label])=>`<div><strong class="${key==='conflict'&&plan.counts[key]?'err':''}">${plan.counts[key]}</strong>${label}</div>`).join('')}</div>${plan.errors.length?`<div class="error-list" role="alert">${plan.errors.map(e=>`<p>${h(e)}</p>`).join('')}<p><strong>存在错误，整批不会写入。</strong></p></div>`:''}<p class="import-scroll-help">预检查只展示本次涉及的语言；每项多语言同一行，可向右滚动对照差异。</p><div class="import-table message-import-table wide-import-table"><table class="data-table" style="min-width:${380+plan.locales.length*190}px"><colgroup><col style="width:44px"><col style="width:240px"><col style="width:96px">${plan.locales.map(()=>'<col style="width:190px">').join('')}</colgroup><thead><tr><th>行</th><th>错误码 / Block</th><th>内容项</th>${plan.locales.map(id=>`<th>${h(language(id))}<span class="cell-sub">${id}</span></th>`).join('')}</tr></thead><tbody>${plan.displayRows.map(row=>`<tr><td>${row.line}</td><td><code>${h(row.code)}</code>${row.blockId?`<span class="cell-sub">${h(row.blockId)}</span>`:''}</td><td>${h(fieldLabel(row.field))}</td>${plan.locales.map(id=>{const c=row.cells[id];return `<td class="import-message">${c?`${tag(STATUS_LABELS[c.status],c.status==='added'?'success':c.status==='updated'?'warning':'')}${c.status==='updated'?`<div class="import-before">${h(c.before)}</div>`:''}<div class="import-after">${h(c.after)}</div>`:'<span class="muted">保留</span>'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><p class="muted mt">${plan.displayRows.length} 项，${plan.targets.length} 个错误码语言组合；统计按非空语言单元格计数。任何错误都会阻止整批导入。</p></section>`:''}`,`<span class="muted">确认前不会修改任何文案</span>${btn('取消','close')}${btn('预检查','message-inspect',!ui.messageRows||ui.busy||!canImport()?'disabled':'')}${btn(ui.busy?'导入中':'确认导入','message-confirm',!plan?.valid||ui.busy||!canImport()?'disabled':'','primary')}`, 'min(1120px, calc(100% - 12px))');}
function inspectMessages(){if(!canImport())return;ui.errors.file='';try{ui.messagePlan=inspectMessageImport(dbState,ui.messageRows);}catch(e){ui.messagePlan=null;ui.errors.file=e.message;}renderEditor();}
async function readMessages(file){if(!file||!canImport())return;ui.messageName=file.name;ui.messageRows=null;ui.messagePlan=null;ui.errors.file='';try{ui.messageRows=parseMessageFile(await file.text(),file.name);}catch(e){ui.errors.file='文件解析失败：'+e.message;}renderEditor();}
function confirmMessages(){if(!canImport()||!ui.messagePlan?.valid)return;const p=clone(ui.messagePlan);if(!p.counts.added&&!p.counts.updated){ui.overlay=null;render();toast('全部文案无变化，无需写入。','info');return;}askConfirm('确认批量导入文案',`<p>将写入 ${p.counts.added} 个新增语言单元格、${p.counts.updated} 个更新语言单元格，涉及 ${p.targets.length} 个错误码语言组合。</p><div class="confirm-impact"><span>包括标题、摘要和正文 Block；整批保存。</span><span>空白字段及文件未包含的语言、Block 保留原内容。</span><span>正文 Block 数量、顺序及前缀保持已有手动配置。</span></div>`,()=>{if(!canImport())throw new Error('没有文案导入权限，本次未写入。');return commit(next=>applyMessageImport(next,p,now()),'批量导入错误码文案',p.baseVersion);},'message-import','确认导入');}
function downloadText(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('文件已下载。','info');}
function bold(targetId){const t=$(targetId),selection=window.getSelection();if(!selection||selection.isCollapsed||!t.contains(selection.anchorNode)||!t.contains(selection.focusNode)){toast('请先选择需要加粗的文字。','info');t.focus();return;}t.focus();document.execCommand('bold');currentContent().blocks[Number(t.dataset.block)][t.dataset.field]=editableText(t);}
function reorder(c){c.structure.forEach((b,i)=>b.order=i+1);syncTranslations(c);}
document.addEventListener('paste',e=>{if(!e.target.isContentEditable)return;e.preventDefault();document.execCommand('insertText',false,normalizeText(e.clipboardData.getData('text/plain')));});
document.addEventListener('mousedown',e=>{if(e.target.closest('[data-action="bold"]'))e.preventDefault();});
document.addEventListener('click',event=>{
 const note=event.target.closest('[data-note]');if(note){event.preventDefault();selectNote(Number(note.dataset.note));return;}
 const t=event.target.closest('[data-action]');if(!t||t.disabled||ui.busy)return;const action=t.dataset.action;
 const capability={general:'edit','save-general':'edit','add-block':'edit','move-block':'edit','remove-block':'edit',bold:'edit','new-code':'manage','edit-metadata':'manage','save-metadata':'manage','load-normal':'manage','load-conflict':'manage',inspect:'manage','import-confirm':'manage','message-sample':'import','message-conflict':'import','message-inspect':'import','message-confirm':'import','export-messages':'export'}[action];if(loadError||!ui.permissions.view||(capability&&!allowed(capability)))return;
 if(action==='tab'){ui.view=t.dataset.view;ui.filter={query:''};ui.page=1;render();}
 else if(action==='search'){ui.filter.query=$('searchQuery').value;ui.page=1;render();}
 else if(action==='reset-filter'){ui.filter={query:''};ui.page=1;render();}
 else if(action==='previous'||action==='next'){ui.page+=action==='next'?1:-1;render();}
 else if(action==='retry'){ui.scenario='normal';$('demoState').value='normal';render();toast('配置已重新加载。');}
 else if(action==='new-code')openMetadata();
 else if(action==='edit-metadata')openMetadata(t.dataset.code);
 else if(action==='save-metadata')saveMetadata();
 else if(action==='full-copy')showFullCopy(t,true);
 else if(action==='general')openGeneral(t.dataset.code);
 else if(action==='close')close();else if(action==='save-general')saveGeneral();
 else if(action==='locale'){ui.locale=t.dataset.locale;renderEditor();$('overlayRoot').querySelector('.drawer-body').scrollTop=0;}
 else if(action==='add-block'){allocateBlock(ui.draft);renderEditor();$('block-'+(ui.draft.structure.length-1)+'-primary').focus();}
 else if(action==='move-block'){const c=ui.draft,i=Number(t.dataset.index),j=i+Number(t.dataset.direction);[c.structure[i],c.structure[j]]=[c.structure[j],c.structure[i]];reorder(c);renderEditor();}
 else if(action==='remove-block'){ui.draft.structure.splice(Number(t.dataset.index),1);reorder(ui.draft);renderEditor();}
 else if(action==='bold')bold(t.dataset.target);
 else if(action==='open-import'){ui.overlay='import';ui.importRows=null;ui.importName='';ui.plan=null;ui.errors={};renderEditor();}
 else if(action==='load-normal'||action==='load-conflict'){if(!canManage())return;showProductPane();ui.importRows=sampleRows(action==='load-normal'?'normal':'conflict');ui.importName=action==='load-normal'?'error-code-example.csv':'error-code-conflict.json';ui.plan=null;ui.errors={};inspect();}
 else if(action==='inspect')inspect();else if(action==='import-confirm')importConfirm();
 else if(action==='download-code-template')download('template');
 else if(action==='download-sample'||action==='download-conflict')download(action==='download-conflict'?'conflict':'normal');
 else if(action==='confirm-submit')submitConfirm();else if(action==='cancel-confirm')cancelConfirm();
 else if(action==='open-message-import')openMessageImport();
 else if(action==='message-sample'||action==='message-conflict'){if(!canImport())return;showProductPane();ui.messageRows=messageSample(dbState,action==='message-conflict');ui.messageName=action==='message-conflict'?'block-messages-conflict.csv':'block-messages-example.csv';inspectMessages();}
 else if(action==='message-inspect')inspectMessages();else if(action==='message-confirm')confirmMessages();
 else if(action==='message-template')downloadText(messageCSV(exportMessageRows(dbState)),'error-content-template.csv','text/csv;charset=utf-8');
 else if(action==='message-json')downloadText(JSON.stringify(messageSample(dbState),null,2),'error-content-example.json','application/json');
 else if(action==='export-messages'&&canExport())downloadText(messageCSV(exportMessageRows(dbState)),'error-content-export.csv','text/csv;charset=utf-8');
});
document.addEventListener('input',e=>{const t=e.target;if(ui.overlay==='metadata'){if(t.id==='metadataCode')ui.metadata.code=t.value;if(t.id==='metadataDescription')ui.metadata.description=t.value;}if(!ui.draft)return;if(t.dataset.content)currentContent()[t.dataset.content]=t.value;if(t.dataset.block!==undefined){const b=['primary','secondary'].includes(t.dataset.field)?currentContent().blocks[Number(t.dataset.block)]:ui.draft.structure[Number(t.dataset.block)];b[t.dataset.field]=t.isContentEditable?editableText(t):t.value;if(t.dataset.field==='number')t.closest('.block-card').querySelector('.prefix-symbol').textContent=t.value;}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.permission){ui.permissions[t.dataset.permission]=t.checked;ui.overlay=null;ui.draft=null;render();}if(t.id==='demoState'){ui.scenario=t.value;render();}if(t.id==='demoFault')ui.fault=t.value;if(t.id==='codeFile')readCodes(t.files[0]);if(t.id==='messageFile')readMessages(t.files[0]);if(t.dataset.block!==undefined&&t.tagName==='SELECT'){const b=ui.draft.structure[Number(t.dataset.block)];b[t.dataset.field]=t.value;if(t.dataset.field==='prefixType'){if(t.value==='icon'){b.icon=ICONS[0][0];b.number='';}else if(t.value==='number'){b.number=String(b.order);b.icon='';}else{b.number='';b.icon='';}}if(['prefixType','icon'].includes(t.dataset.field))renderEditor();}});
document.addEventListener('dragover',e=>{const z=e.target.closest('#dropzone,#messageDropzone');if(z){e.preventDefault();z.classList.add('dragover');}});
document.addEventListener('dragleave',e=>e.target.closest('#dropzone,#messageDropzone')?.classList.remove('dragover'));
document.addEventListener('drop',e=>{if(e.target.closest('#dropzone,#messageDropzone')){e.preventDefault();ui.overlay==='message-import'?readMessages(e.dataTransfer.files[0]):readCodes(e.dataTransfer.files[0]);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.overlay&&!ui.busy)close();if(e.key==='Enter'&&e.target.id==='searchQuery'){e.preventDefault();document.querySelector('[data-action="search"]').click();}if(e.key==='Enter'&&e.target.closest('.note-card[data-note]'))selectNote(Number(e.target.closest('[data-note]').dataset.note));if(e.key==='Tab'&&ui.overlay){const dialog=$('overlayRoot').querySelector('[role=dialog]');const nodes=[...dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[contenteditable=true]')].filter(n=>n.offsetParent!==null);if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0]?.focus();}}});
$('navError').addEventListener('click',()=>{ui.view='catalog';ui.overlay=null;render();});
$('resetDemo').addEventListener('click',()=>{if(ui.busy)return;loadError='';persist(initialState());Object.assign(ui,{view:'catalog',overlay:null,draft:null,scenario:'normal',fault:'none',permissions:{view:true,manage:true,edit:true,import:true,export:true},filter:{query:''},page:1,errors:{},plan:null,messagePlan:null});document.querySelectorAll('[data-permission]').forEach(t=>t.checked=true);$('demoState').value='normal';$('demoFault').value='none';render();toast('演示数据已重置。','info');});
document.querySelectorAll('[data-mobile]').forEach(b=>b.addEventListener('click',()=>{$('reviewShell').classList.toggle('notes-mode',b.dataset.mobile==='notes');document.querySelectorAll('[data-mobile]').forEach(x=>x.classList.toggle('active',x===b));}));
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY&&e.newValue){try{dbState=migrateState(JSON.parse(e.newValue));renderMain();if(!ui.overlay)renderNotes();}catch{toast('其他窗口的数据无法读取，请重新加载。','error');}}});
function alignCanvas(){hideFullCopy();if(window.innerWidth<=900)$('productViewport').scrollTo({left:208,top:0});positionAnchors();}
render();alignCanvas();$('productViewport').addEventListener('scroll',positionAnchors,{passive:true});window.addEventListener('resize',alignCanvas);
if(migrated)toast('旧数据已完整备份，用户编辑与结构已保留；未编辑的默认样例文案已更新。','info');

function hideFullCopy(){document.getElementById('fullCopyPopover')?.remove();copyPinned=false;}
function showFullCopy(target,pinned=false){
 if(!ui.permissions.view||ui.overlay)return;
 const copy=dbState.codes[target.dataset.code]?.content[target.dataset.locale];if(!copy)return;
 hideFullCopy();copyPinned=pinned;
 const panel=document.createElement('aside');panel.id='fullCopyPopover';panel.className='full-copy-popover';panel.setAttribute('role',pinned?'dialog':'tooltip');panel.setAttribute('aria-label','标题和摘要全文');
 panel.innerHTML=`<div class="full-copy-heading"><strong>${h(language(target.dataset.locale))}</strong>${pinned?'<button class="icon-btn" aria-label="关闭全文">×</button>':''}</div><span class="muted">标题</span><p>${h(copy.title)||'未配置标题'}</p><span class="muted">摘要</span><p>${h(copy.summary)||'未配置摘要'}</p>`;
 document.body.append(panel);panel.querySelector('button')?.addEventListener('click',()=>{hideFullCopy();target.focus({preventScroll:true});hideFullCopy();});
 const r=target.getBoundingClientRect(),width=Math.min(380,window.innerWidth-24);panel.style.width=width+'px';panel.style.left=Math.max(12,Math.min(r.left,window.innerWidth-width-12))+'px';
 const height=panel.getBoundingClientRect().height;panel.style.top=Math.max(12,Math.min(r.bottom+8,window.innerHeight-height-12))+'px';
}
document.addEventListener('pointerover',e=>{const t=e.target.closest('.locale-copy');if(t&&!copyPinned)showFullCopy(t);});
document.addEventListener('pointerout',e=>{if(e.target.closest('.locale-copy')&&!e.relatedTarget?.closest('.locale-copy,#fullCopyPopover')&&!copyPinned)hideFullCopy();});
document.addEventListener('focusin',e=>{const t=e.target.closest('.locale-copy');if(t)showFullCopy(t);});
document.addEventListener('focusout',e=>{if(e.target.closest('.locale-copy')&&!copyPinned)hideFullCopy();});
document.addEventListener('click',e=>{if(!e.target.closest('.locale-copy,#fullCopyPopover'))hideFullCopy();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')hideFullCopy();});
document.addEventListener('scroll',e=>{if(!e.target.closest?.('#fullCopyPopover'))hideFullCopy();},true);
